CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS admins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL DEFAULT 'admin' CHECK(role IN ('admin','tl')), is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE admins ADD COLUMN IF NOT EXISTS role text NOT NULL DEFAULT 'admin';
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='admins_role_check') THEN ALTER TABLE admins ADD CONSTRAINT admins_role_check CHECK (role IN ('admin','tl')); END IF; END $$; 
CREATE TABLE IF NOT EXISTS site_settings (id int PRIMARY KEY DEFAULT 1 CHECK(id=1), data jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trips (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, title text NOT NULL, subtitle text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', cover text NOT NULL DEFAULT '', start_date date, end_date date, participant_min int DEFAULT 0, participant_max int DEFAULT 0, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), visibility text NOT NULL DEFAULT 'public' CHECK(visibility IN ('public','private')), private_token_hash text UNIQUE, featured boolean NOT NULL DEFAULT false, location text NOT NULL DEFAULT '', reminder text NOT NULL DEFAULT '', days jsonb NOT NULL DEFAULT '[]', destination_ids jsonb NOT NULL DEFAULT '[]', stops jsonb NOT NULL DEFAULT '[]', infos jsonb NOT NULL DEFAULT '[]', gallery jsonb NOT NULL DEFAULT '[]', published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_trips_public ON trips(status,visibility,published_at DESC);
CREATE TABLE IF NOT EXISTS destinations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, name text NOT NULL, region text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'Alam', description text NOT NULL DEFAULT '', tips text NOT NULL DEFAULT '', image text NOT NULL DEFAULT '', latitude double precision, longitude double precision, featured boolean DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), path text NOT NULL, alt_text text NOT NULL DEFAULT '', mime_type text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id bigserial PRIMARY KEY, admin_id uuid REFERENCES admins(id) ON DELETE SET NULL, action text NOT NULL, entity text NOT NULL, entity_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tl_trip_assignments (tl_id uuid NOT NULL REFERENCES admins(id) ON DELETE CASCADE, trip_id uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE, assigned_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tl_id,trip_id));
CREATE TABLE IF NOT EXISTS tl_tracking_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trip_id uuid NOT NULL REFERENCES trips(id) ON DELETE CASCADE, tl_id uuid NOT NULL REFERENCES admins(id) ON DELETE RESTRICT, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','completed','stopped')), share_location boolean NOT NULL DEFAULT false, started_at timestamptz NOT NULL DEFAULT now(), stopped_at timestamptz, last_location_at timestamptz, last_latitude double precision, last_longitude double precision, last_accuracy_meters double precision, current_checkpoint integer NOT NULL DEFAULT 0, CHECK(last_latitude IS NULL OR last_latitude BETWEEN -90 AND 90), CHECK(last_longitude IS NULL OR last_longitude BETWEEN -180 AND 180));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_tl_session ON tl_tracking_sessions(trip_id) WHERE status='active';
CREATE TABLE IF NOT EXISTS tl_tracking_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES tl_tracking_sessions(id) ON DELETE CASCADE, event_type text NOT NULL, checkpoint integer, latitude double precision, longitude double precision, accuracy_meters double precision, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS tl_events_session_time ON tl_tracking_events(session_id,created_at DESC); 

ALTER TABLE tl_tracking_sessions ADD COLUMN IF NOT EXISTS checkpoints jsonb NOT NULL DEFAULT '[]';
